<script setup lang="ts">
// 标签管理页：/manage/tag（管理 tab 侧边栏）。
//
// 2026-10-12 叫法统一后的定位：一行 = 一个概念（通用名），行内列出它的全部叫法。
// 每个叫法都是 tag 表的一行、都有自己的 id，所以每个叫法都能单独治理：
//   改名（任意叫法） / 设为通用名 / 拆分（独立成新标签）
// 行级动作：置顶排序、合并到其他标签。
//
// 为什么把「改名 / 设为通用名 / 拆分」挂在叫法上而不是行上：
// 用户的原话是「理论上每个标签都应该能修改」——他说的「标签」就是屏幕上那个词，
// 不是「这个概念」。把操作挂在叫法上，点哪个词就改哪个词，不需要先想清楚
// 「它是不是通用名」。合并/拆分只改 concept_id，题目关联一行都不动。
import { computed, onMounted, ref, watch } from "vue";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsError, ShowTextTipsSuccess } from "@/util/tips";
import {
  GetEnrichTagManageList,
  PostEnrichTagMerge,
  PostEnrichTagPin,
  PostEnrichTagRename,
  PostEnrichTagSetPrimary,
  PostEnrichTagSplit,
} from "@/apis/problem-enrichment";
import type { EnrichTag, EnrichTagManageItem } from "@/types/problem-enrichment";
import { useBreakpoint } from "@/composables/useBreakpoint";

const { globalProperties } = useCurrentInstance();
const { isMobile } = useBreakpoint();

// 展示名长度上限：与后端 tagNameMaxRunes 对齐（数据库列在迁移里放宽到 64 只为容纳
// 历史长别名，人工操作仍限制 20 字，避免列表被超长标签撑坏）
const TAG_NAME_MAX = 20;

// 每页条数：默认随断点（移动端一屏能扫的行更少），也允许用户自己改
const pageSize = ref(isMobile.value ? 20 : 50);

// ── 筛选与列表 ──
const loading = ref(false);
const list = ref<EnrichTagManageItem[]>([]);
const total = ref(0);
const page = ref(1);
const keyword = ref("");
// 已提交的检索词：只有回车/点搜索才更新，避免每敲一个字都打一次后端
const submittedKeyword = ref("");

const columns = [
  { colKey: "name", title: "标签（通用名）", minWidth: 180 },
  { colKey: "members", title: "全部叫法", minWidth: 280 },
  { colKey: "problem_count", title: "挂题数", width: 88, align: "center" as const },
  { colKey: "source", title: "来源", width: 76, align: "center" as const },
  // 操作列宽按最长一行文案预留：合并到…（5 字）+ 取消置顶（4 字）+ 上移 + 下移，
  // 12px 字号下合计约 224px，加上单元格 24px 内边距后 232 装不下会折成两行（原来就是这样），
  // 放宽到 264 并收紧按钮内边距，保证始终一行
  { colKey: "operation", title: "操作", width: 264, fixed: "right" as const },
];

const fetchList = async () => {
  loading.value = true;
  try {
    const res = await GetEnrichTagManageList(
      submittedKeyword.value,
      page.value,
      pageSize.value
    );
    if (res.code === 0) {
      list.value = res.data?.list ?? [];
      total.value = res.data?.total ?? 0;
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "加载标签列表失败");
  } finally {
    loading.value = false;
  }
};

// 回车或点「搜索」才提交关键词
const onKeywordSubmit = () => {
  submittedKeyword.value = keyword.value.trim();
  page.value = 1;
  fetchList();
};

const onPageChange = () => {
  fetchList();
};

const onPageSizeChange = () => {
  page.value = 1;
  fetchList();
};

// 断点切换会改变每页条数：回到第一页重取，避免页码指到不存在的页
watch(isMobile, (mobile) => {
  pageSize.value = mobile ? 20 : 50;
  page.value = 1;
  fetchList();
});

// ── 叫法辅助 ──
// 概念行的 id 就是通用名行的 id（后端只返回通用名行），members 里排第一的就是它。
// 这里不假设顺序，按 id 比较：排序契约万一变了也不会把通用名认错。
const membersOf = (row: EnrichTagManageItem): EnrichTag[] => row.members ?? [];
const isPrimary = (row: EnrichTagManageItem, call: EnrichTag) => call.id === row.id;

// 叫法的操作菜单。通用名与别名共用同一套动作，只有「设为通用名」「拆分」对通用名无意义：
// 已经是通用名就没有可设的；通用名不能拆——拆了源概念就没有展示名（后端返回 100128）。
const callMenuOptions = (row: EnrichTagManageItem, call: EnrichTag) => {
  const options: { content: string; value: string; disabled?: boolean }[] = [];
  if (!isPrimary(row, call)) {
    options.push({ content: "设为通用名", value: "primary" });
  }
  options.push({ content: "改名", value: "rename" });
  if (isPrimary(row, call)) {
    options.push({ content: "通用名不可拆分", value: "split", disabled: true });
  } else {
    options.push({ content: "拆分为独立标签", value: "split" });
  }
  return options;
};

const onCallMenu = (row: EnrichTagManageItem, call: EnrichTag, data: { value: string }) => {
  switch (data.value) {
    case "primary":
      setPrimaryCall(row, call);
      break;
    case "rename":
      openRenameDialog(row, call);
      break;
    case "split":
      splitCall(row, call);
      break;
    default:
      break;
  }
};

// ── 设为通用名：纯展示层的选择，不动任何题目关联 ──
const setPrimaryCall = async (row: EnrichTagManageItem, call: EnrichTag) => {
  try {
    const res = await PostEnrichTagSetPrimary(call.id);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    ShowTextTipsSuccess(
      globalProperties,
      `通用名已改为「${call.name}」，旧通用名「${row.name}」降为普通叫法`
    );
    await fetchList();
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "设置通用名失败");
  }
};

// ── 改名：每个叫法都能改（旧名直接废弃、不降为别名） ──
const renameVisible = ref(false);
const renameRow = ref<EnrichTagManageItem | null>(null);
const renameCall = ref<EnrichTag | null>(null);
const renameName = ref("");
const renameSubmitting = ref(false);

const renameLength = computed(() => Array.from(renameName.value.trim()).length);
const renameValid = computed(
  () => renameLength.value > 0 && renameLength.value <= TAG_NAME_MAX
);

const openRenameDialog = (row: EnrichTagManageItem, call: EnrichTag) => {
  renameRow.value = row;
  renameCall.value = call;
  renameName.value = call.name;
  renameVisible.value = true;
};

const handleRenameSubmit = async () => {
  const call = renameCall.value;
  if (!call || !renameValid.value) {
    return;
  }
  renameSubmitting.value = true;
  try {
    const res = await PostEnrichTagRename(call.id, renameName.value.trim());
    if (res.code === 0) {
      ShowTextTipsSuccess(globalProperties, `叫法「${call.name}」已改名为「${renameName.value.trim()}」`);
      renameVisible.value = false;
      await fetchList();
    } else {
      // 100126 重名 / 100127 名字非法：后端给的就是可读的业务提示
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "改名失败");
  } finally {
    renameSubmitting.value = false;
  }
};

// ── 拆分：斩断这个叫法与源概念的联系，它自己成为独立标签 ──
// 题目挂的是**具体叫法**，所以挂在它上面的题自然跟着它走，不需要搬任何关联。
const splitCall = async (row: EnrichTagManageItem, call: EnrichTag) => {
  try {
    const res = await PostEnrichTagSplit([call.id]);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    ShowTextTipsSuccess(
      globalProperties,
      `「${call.name}」已从「${row.name}」拆出成为独立标签：挂在它上面的题目跟着它走`
    );
    await fetchList();
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "拆分失败");
  }
};

// ── 合并：把这一行（概念）并入另一个标签，本行成为对方的别名 ──
const mergeVisible = ref(false);
const mergeRow = ref<EnrichTagManageItem | null>(null);
const mergeTargetId = ref<number | null>(null);
const mergeOptions = ref<{ label: string; value: number }[]>([]);
const mergeSearching = ref(false);
const mergeSubmitting = ref(false);

const openMergeDialog = (row: EnrichTagManageItem) => {
  mergeRow.value = row;
  mergeTargetId.value = null;
  mergeOptions.value = [];
  mergeVisible.value = true;
  searchMergeTargets("");
};

// 目标标签用远程搜索：标签表有几百行，一次性铺进下拉很难找。
// 复用管理页列表接口（它同时匹配通用名与别名），因此按别名也能搜到目标。
const searchMergeTargets = async (kw: string) => {
  mergeSearching.value = true;
  try {
    const res = await GetEnrichTagManageList(kw.trim(), 1, 20);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    const selfId = mergeRow.value?.id;
    mergeOptions.value = (res.data?.list ?? [])
      .filter((item) => item.id !== selfId)
      .map((item) => ({
        label: `${item.name}（挂题 ${item.problem_count}）`,
        value: item.id,
      }));
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "搜索目标标签失败");
  } finally {
    mergeSearching.value = false;
  }
};

const handleMergeSubmit = async () => {
  const row = mergeRow.value;
  const targetId = mergeTargetId.value;
  if (!row || !targetId) {
    return;
  }
  mergeSubmitting.value = true;
  try {
    const res = await PostEnrichTagMerge(targetId, [row.id]);
    if (res.code === 0) {
      const targetLabel = mergeOptions.value.find((o) => o.value === targetId)?.label ?? "";
      ShowTextTipsSuccess(
        globalProperties,
        `「${row.name}」已并入「${targetLabel}」并成为它的别名；题目关联未变`
      );
      mergeVisible.value = false;
      await fetchList();
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "合并失败");
  } finally {
    mergeSubmitting.value = false;
  }
};

// ── 置顶 / 排序：只影响标签列表的展示顺序，不改变标签语义 ──
// 新置顶追加到置顶区末尾（取现有最大 order + 1），取消时归零。
//
// 顺序由后端统一决定（pinned DESC, pin_order ASC, 最近活跃…），本地只改 row 上的
// pinned/pin_order 不会让这一行移动——置顶后它仍停在原地，上移/下移更是完全看不出来，
// 用户会以为「点了没反应」。所以每次成功都重取当前页，让行按后端顺序重新落位。
const togglePin = async (row: EnrichTagManageItem) => {
  const nextPinned = !row.pinned;
  const maxOrder = list.value
    .filter((t) => t.pinned)
    .reduce((max, t) => Math.max(max, t.pin_order ?? 0), 0);
  const nextOrder = nextPinned ? maxOrder + 1 : 0;
  try {
    const res = await PostEnrichTagPin(row.id, nextPinned, nextOrder);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    ShowTextTipsSuccess(
      globalProperties,
      nextPinned ? "已置顶：它会固定出现在标签列表最前" : "已取消置顶"
    );
    await fetchList();
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  }
};

// 置顶区内上移 / 下移：与相邻的置顶标签**交换** pin_order。
//
// 用两次 SetTagPinned 而不是新开一个 swap 接口——置顶是低频操作，
// 省一个接口、少一处后端逻辑值得。两次调用之间若失败，两个标签会拿到相同的
// pin_order，此时排序由时间兜底，不会出现「标签消失」这类硬故障。
// 交换完同样要重取：只有后端重排后，两行才会真的换位置。
const movePin = async (row: EnrichTagManageItem, delta: number) => {
  const pinnedList = list.value
    .filter((t) => t.pinned)
    .sort((a, b) => (a.pin_order ?? 0) - (b.pin_order ?? 0));
  const idx = pinnedList.findIndex((t) => t.id === row.id);
  const target = idx >= 0 ? pinnedList[idx + delta] : undefined;
  if (!target) {
    return;
  }
  const myOrder = row.pin_order ?? 0;
  const targetOrder = target.pin_order ?? 0;
  try {
    const first = await PostEnrichTagPin(row.id, true, targetOrder);
    if (first.code !== 0) {
      ShowErrorTips(globalProperties, first.code);
      return;
    }
    const second = await PostEnrichTagPin(target.id, true, myOrder);
    if (second.code !== 0) {
      ShowErrorTips(globalProperties, second.code);
      return;
    }
    ShowTextTipsSuccess(globalProperties, delta < 0 ? "已上移" : "已下移");
    await fetchList();
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  }
};

onMounted(() => {
  fetchList();
});
</script>

<template>
  <div class="manage-tag">
    <!-- 筛选区 -->
    <div class="mt-toolbar">
      <t-input
        v-model="keyword"
        class="mt-keyword"
        placeholder="按通用名或任一叫法搜索，回车检索"
        clearable
        @enter="onKeywordSubmit"
        @clear="onKeywordSubmit"
      />
      <t-button theme="primary" variant="outline" @click="onKeywordSubmit">搜索</t-button>
      <t-button variant="outline" @click="fetchList">刷新</t-button>
      <span class="mt-muted">共 {{ total }} 个标签</span>
    </div>
    <p class="mt-hint">
      点任意叫法可改名、设为通用名或拆分为独立标签；通用名只用于标签列表展示，
      问题展示的始终是它自己挂的那个叫法。
    </p>

    <!-- 桌面端：一个概念一行，行内列出全部叫法 -->
    <div v-if="!isMobile" class="mt-table-wrap">
      <t-table
        :data="list"
        :columns="columns"
        :loading="loading"
        row-key="id"
        stripe
        hover
        table-layout="fixed"
        class="mt-table"
      >
        <template #name="{ row }">
          <div class="mt-name-cell">
            <span class="mt-name">{{ row.name }}</span>
            <t-tag v-if="row.pinned" size="small" theme="warning" variant="light">置顶</t-tag>
          </div>
        </template>
        <template #members="{ row }">
          <div class="mt-calls">
            <t-dropdown
              v-for="call in membersOf(row)"
              :key="call.id"
              trigger="click"
              :options="callMenuOptions(row, call)"
              @click="(data: { value: string }) => onCallMenu(row, call, data)"
            >
              <t-tag
                size="small"
                class="mt-call"
                :theme="isPrimary(row, call) ? 'primary' : 'default'"
                :variant="isPrimary(row, call) ? 'light' : 'light-outline'"
              >
                {{ call.name }}
              </t-tag>
            </t-dropdown>
          </div>
        </template>
        <template #problem_count="{ row }">
          <span class="mt-count">{{ row.problem_count }}</span>
        </template>
        <template #source="{ row }">
          <t-tag size="small" :theme="row.source === 'ai' ? 'primary' : 'success'" variant="outline">
            {{ row.source === "ai" ? "AI" : "人工" }}
          </t-tag>
        </template>
        <template #operation="{ row }">
          <t-space class="mt-ops" size="small">
            <t-button size="small" variant="text" theme="primary" @click="openMergeDialog(row)">
              合并到…
            </t-button>
            <t-button
              size="small"
              variant="text"
              :theme="row.pinned ? 'warning' : 'default'"
              @click="togglePin(row)"
            >
              {{ row.pinned ? "取消置顶" : "置顶" }}
            </t-button>
            <template v-if="row.pinned">
              <t-button size="small" variant="text" @click="movePin(row, -1)">上移</t-button>
              <t-button size="small" variant="text" @click="movePin(row, 1)">下移</t-button>
            </template>
          </t-space>
        </template>
      </t-table>
    </div>

    <!-- 移动端：同一份数据换成卡片（tdesign 没有 Cell/SwipeCell，用原生 div） -->
    <div v-else class="mt-cards">
      <div v-if="list.length === 0 && !loading" class="mt-empty">没有符合条件的标签</div>
      <div v-for="row in list" :key="row.id" class="mt-card">
        <div class="mt-card-head">
          <span class="mt-name">{{ row.name }}</span>
          <t-tag v-if="row.pinned" size="small" theme="warning" variant="light">置顶</t-tag>
          <span class="mt-muted">挂题 {{ row.problem_count }}</span>
        </div>
        <div class="mt-calls">
          <t-dropdown
            v-for="call in membersOf(row)"
            :key="call.id"
            trigger="click"
            :options="callMenuOptions(row, call)"
            @click="(data: { value: string }) => onCallMenu(row, call, data)"
          >
            <t-tag
              size="small"
              class="mt-call"
              :theme="isPrimary(row, call) ? 'primary' : 'default'"
              :variant="isPrimary(row, call) ? 'light' : 'light-outline'"
            >
              {{ call.name }}
            </t-tag>
          </t-dropdown>
        </div>
        <div class="mt-card-actions">
          <t-button size="small" variant="text" theme="primary" @click="openMergeDialog(row)">
            合并到…
          </t-button>
          <t-button
            size="small"
            variant="text"
            :theme="row.pinned ? 'warning' : 'default'"
            @click="togglePin(row)"
          >
            {{ row.pinned ? "取消置顶" : "置顶" }}
          </t-button>
          <template v-if="row.pinned">
            <t-button size="small" variant="text" @click="movePin(row, -1)">上移</t-button>
            <t-button size="small" variant="text" @click="movePin(row, 1)">下移</t-button>
          </template>
        </div>
      </div>
    </div>

    <div class="mt-pagination">
      <t-pagination
        v-model="page"
        v-model:page-size="pageSize"
        :total="total"
        :page-size-options="[20, 50, 100]"
        show-jumper
        @current-change="onPageChange"
        @page-size-change="onPageSizeChange"
      />
    </div>

    <!-- 改名：通用名与别名一视同仁 -->
    <t-dialog
      v-model:visible="renameVisible"
      :header="renameCall ? `改叫法：${renameCall.name}` : '改叫法'"
      width="560px"
      :confirm-on-enter="false"
      :confirm-loading="renameSubmitting"
      :confirm-btn="{ disabled: !renameValid }"
      @confirm="handleRenameSubmit"
    >
      <p class="mt-dialog-text">
        所属标签：<b>{{ renameRow?.name }}</b>
        <t-tag
          v-if="renameCall && renameRow && isPrimary(renameRow, renameCall)"
          size="small"
          theme="primary"
          variant="light"
          class="mt-dialog-tag"
        >
          通用名
        </t-tag>
        <t-tag v-else size="small" variant="light-outline" class="mt-dialog-tag">别名</t-tag>
      </p>
      <p class="mt-dialog-text">
        改名会把旧叫法直接替换为新叫法，旧叫法<strong>不保留</strong>为别名。
        改通用名即改这个标签的展示名；改别名只换这一个叫法。
      </p>
      <t-input
        v-model="renameName"
        :maxlength="TAG_NAME_MAX"
        placeholder="新的叫法（20 字以内）"
        @enter="handleRenameSubmit"
      />
      <div v-if="renameLength > 0 && !renameValid" class="mt-error">
        叫法最长 {{ TAG_NAME_MAX }} 个字
      </div>
    </t-dialog>

    <!-- 合并：本行概念并入目标标签，本行通用名成为对方的别名 -->
    <t-dialog
      v-model:visible="mergeVisible"
      :header="mergeRow ? `合并「${mergeRow.name}」到其他标签` : '合并标签'"
      width="560px"
      :confirm-btn="{ disabled: !mergeTargetId }"
      :confirm-loading="mergeSubmitting"
      @confirm="handleMergeSubmit"
    >
      <p class="mt-dialog-text">
        被合并的标签会变成目标标签的<strong>别名</strong>，它的全部叫法一并归入目标标签。
      </p>
      <p class="mt-dialog-text">
        <strong>题目关联不会改变</strong>：问题挂的是具体叫法，合并只改叫法的归属，
        每道题显示的仍是它自己设置的那个名字。
      </p>
      <p class="mt-dialog-text">
        本行共 {{ mergeRow?.problem_count ?? 0 }} 道题，叫法：
        {{ (mergeRow ? membersOf(mergeRow) : []).map((m) => m.name).join("、") || "—" }}
      </p>
      <t-select
        v-model="mergeTargetId"
        class="mt-merge-select"
        :options="mergeOptions"
        :loading="mergeSearching"
        filterable
        clearable
        placeholder="搜索目标标签（通用名或别名）"
        @search="searchMergeTargets"
      />
    </t-dialog>
  </div>
